using DT.Model;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace DT.Tools
{
    
    public class Units : MonoBehaviour
    {

        public static Unit GetUnitFromId(string id)
        {
            var unit = UnitList.First(t => t.Id == id);
            if (unit == null)
            {
                Debug.LogError("No Unit found with ID : " + id);
                return unit;
            }
            return unit.Clone();
        }

        public static Unit GetUnitFormIdOrName(string value)
        {
            var unit = UnitList.First(t => t.Id == value || t.Name == value);
            if (unit == null)
            {
                Debug.LogError("No Unit found with ID or Name: " + value);
                return unit;
            }
            return unit.Clone();
        }

        public static Unit GetUnitFromOpcuaId(int code)
        {
            var unit = UnitList.First(t => t.OpcUAId == code);
            if (unit == null)
            {
                Debug.LogError("No Unit found with Opcua ID : " + code);
                return unit;
            }
            return unit.Clone();
        }

        public static Unit GetUnitFromName(string name)
        {
            var unit = UnitList.FirstOrDefault(t => t.Name == name);
            if (unit == null)
            {
                Debug.LogError("No Unit found with name : " + name);
                return unit;
            }
            return unit.Clone();
        }





        public static float ConvertToSI(float value, Unit unit)
        {
            if (unit == null)
            {
                return (float)value;
            }
            return (float)(value * unit.ToSIConvertFactor);
        }
        public static float ConvertFromSI(float value, Unit unit)
        {
            if (unit == null)
            {
                return (float)value;
            }
            return (float)(value / unit.ToSIConvertFactor);
        }

        public static float ConvertFromTo(float value, Unit fromUnit, Unit toUnit)
        {
            return ConvertFromSI(ConvertToSI(value, fromUnit), toUnit);
        }

        public static double ConvertToSI(double value, Unit unit)
        {
            if (unit == null)
            {
                return (double)value;
            }
            return (double)(value * unit.ToSIConvertFactor);
        }
        public static double ConvertFromSI(double value, Unit unit)
        {
            if (unit == null)
            {
                return (double)value;
            }
            return (double)(value / unit.ToSIConvertFactor);
        }

        public static double ConvertFromTo(double value, Unit fromUnit, Unit toUnit)
        {
            return ConvertFromSI(ConvertToSI(value, fromUnit), toUnit);
        }



        public static float ConvertToSI(Parameter param)
        {
            if (param.Unit != null)
            {
                return ConvertToSI(param.Value, param.Unit);
            }
            else { return (float)param.Value; }
        }
        public static float ConvertToSI(Variable var)
        {
            if (var.Unit != null)
            {
                return ConvertToSI(var.Value, var.Unit);
            }
            else { return (float)var.Value; }
        }

